const b = $input.first().json.body || {};
const p = b.parameters || b || {};
const KEY = '<JWT_REDACTED>';
const rates = {solea:149, athena:139, marina:135, luna:129, aurora:119};
function pick(n){ n=(n||'').toLowerCase(); for (const k in rates){ if(n.indexOf(k)>=0) return {rate:rates[k],key:k}; } return {rate:129,key:'luna'}; }
const pr = pick(p.property);
const propName = 'Casa ' + pr.key.charAt(0).toUpperCase() + pr.key.slice(1);
function ymd(d){ return d.toISOString().slice(0,10); }
function addDays(s,n){ const d=new Date(s+'T12:00:00Z'); d.setUTCDate(d.getUTCDate()+n); return ymd(d); }
function isDate(s){ return typeof s==='string' && s.length===10 && s.charAt(4)==='-' && s.charAt(7)==='-'; }
const today = ymd(new Date());
let ci = isDate(p.check_in) ? p.check_in : today;
let nights = parseInt(p.nights);
let co = isDate(p.check_out) ? p.check_out : addDays(ci, (nights>0?nights:1));
nights = Math.max(1, Math.round((new Date(co)-new Date(ci))/86400000));
const cleaning=99; const subtotal=pr.rate*nights; const total=subtotal+cleaning;
const base='https://zkylrolpuwybsksspblj.supabase.co/rest/v1/casas_bookings';
const url = base + '?property=eq.' + encodeURIComponent(propName) + '&status=neq.cancelled&check_in=lt.' + co + '&check_out=gt.' + ci + '&select=id';
let rows=[];
try{ rows = await this.helpers.httpRequest({ method:'GET', url, headers:{ apikey:KEY, Authorization:'Bearer '+KEY }, json:true }); }catch(e){ rows = []; }
const available = Array.isArray(rows) ? rows.length===0 : true;
let result;
if(available){ result = propName + ' is available from ' + ci + ' to ' + co + ' (' + nights + ' night' + (nights>1?'s':'') + ') at $' + pr.rate + ' per night. With the one-time $' + cleaning + ' cleaning fee, the total is $' + total + '. Would you like me to hold it? I just need your name and an email or phone.'; }
else { result = 'I am sorry, ' + propName + ' is not available for ' + ci + ' to ' + co + '. I can check other dates or another apartment - Casa Solea, Casa Athena, Casa Marina, Casa Luna or Casa Aurora.'; }
return [{ json: { result, available, property:propName, check_in:ci, check_out:co, nights, nightly:pr.rate, cleaning, total } }];
